        "id": "inspiration-17-xr-展示型网站-用沉浸式视觉降低空间体验的理解门槛",
        "section": "inspiration",
        "title": "17｜XR 展示型网站：用沉浸式视觉降低空间体验的理解门槛",
        "description": "它适合作为 XR/空间体验类网站的参考，重点观察如何用视觉实验、动效节奏和沉浸式页面结构降低 XR 概念的理解门槛。",
        "longDescription": "它适合作为 XR/空间体验类网站的参考，重点观察如何用视觉实验、动效节奏和沉浸式页面结构降低 XR 概念的理解门槛。\n\n可借鉴点：\n1. XR 类产品官网不能只讲技术名词，需要用沉浸式视觉先建立感知。\n2. 展示型网站可通过动效节奏引导用户理解空间、设备、场景之间的关系。\n3. 首页首屏适合承担“世界观建立”功能，而不是直接堆功能介绍。\n4. 适合 XR、空间计算、沉浸展览、数字艺术、实验型品牌官网参考。",
