        "id": "inspiration-18-触摸驱动的波浪卡片-从横向滑动变成有物理感的浏览体验",
        "section": "inspiration",
        "title": "18｜触摸驱动的波浪卡片：从横向滑动变成有物理感的浏览体验",
        "description": "Wavy Carousel 是 Janum Trivedi 发布的 iPhone 界面动效案例 它用堆叠音乐卡片作为主体，卡片会跟随触摸拖拽产生流动、弯曲和层级变化，让传统 Carousel 从“横向滑动”变成更具物理感的手势反馈。",
        "longDescription": "Wavy Carousel 是 Janum Trivedi 发布的 iPhone 界面动效案例 它用堆叠音乐卡片作为主体，卡片会跟随触摸拖拽产生流动、弯曲和层级变化，让传统 Carousel 从“横向滑动”变成更具物理感的手势反馈。\n可借鉴点：\n1. 卡片轮播不一定只能做平移，也可以加入弯曲、堆叠和弹性形变，增强触摸反馈。\n2. 音乐、播客、封面流、收藏夹这类视觉内容，适合用“物理感卡片”提升浏览愉悦度。\n3. Dark UI 下，卡片层级和运动节奏会比复杂装饰更重要。\n4. 适合音乐 App、内容收藏、作品集浏览、移动端推荐流、封面卡片组件参考。",
