        "longDescription": "点击界面右上角的 Publish 按钮后，一圈波浪形变从触点向外扩散。波纹经过的位置会产生短暂的弯曲和拉伸，最终随着波浪离开画面恢复原状。\n它没有把点击反馈限制在按钮内部，而是让一次局部操作影响整个界面空间。简单说让我联想到海浪🌊",
